  // Multi-layered defeat detection for Dungeon Jailor
  function initDungeonJailorDeathWatcher() {
    // 1. Array push hook on victoryDisplay & encounterDiscard
    function hookPiles() {
      const g = window.game || window.LotrEngine?.game;
      if (!g || !g.victoryDisplay || !g.encounterDiscard) {
        setTimeout(hookPiles, 100);
        return;
      }
      if (!g.victoryDisplay._jailorHooked) {
        const origVDPush = g.victoryDisplay.push;
        g.victoryDisplay.push = function(...items) {
          for (const item of items) {
            if (item && (item.id === 'dungeon_jailor' || item.id === 'dungeon_jailer' || item.name === 'Dungeon Jailor' || item.name === 'Dungeon Jailer')) {
              playDungeonJailorDiesImmediately();
            }
          }
          return origVDPush.apply(this, arguments);
        };
        g.victoryDisplay._jailorHooked = true;
      }
      if (!g.encounterDiscard._jailorHooked) {
        const origEDPush = g.encounterDiscard.push;
        g.encounterDiscard.push = function(...items) {
          for (const item of items) {
            if (item && (item.id === 'dungeon_jailor' || item.id === 'dungeon_jailer' || item.name === 'Dungeon Jailor' || item.name === 'Dungeon Jailer')) {
              playDungeonJailorDiesImmediately();
            }
          }
          return origEDPush.apply(this, arguments);
        };
        g.encounterDiscard._jailorHooked = true;
      }
    }
    hookPiles();

    // 2. DOM MutationObserver watching for "Dungeon Jailor is destroyed" / "Enemy Defeated! Dungeon Jailor" toasts and log entries
    const checkDeathText = (node) => {
      if (!node || node.nodeType !== 1 || node.tagName === 'SCRIPT' || node.tagName === 'STYLE') return;
      const txt = (node.textContent || '').trim();
      if ((txt.includes('Dungeon Jailor') || txt.includes('Dungeon Jailer')) && (txt.includes('destroyed') || txt.includes('Defeated') || txt.includes('Enemy Defeated') || txt.includes('victory') || txt.includes('Victory'))) {
        playDungeonJailorDiesImmediately();
      }
    };

    const deathObs = new MutationObserver((mutations) => {
      for (const m of mutations) {
        for (const n of m.addedNodes) {
          checkDeathText(n);
        }
      }
    });

    const tc = document.getElementById('toast-container');
    if (tc) deathObs.observe(tc, { childList: true, subtree: true });
    const gl = document.getElementById('game-log-content');
    if (gl) deathObs.observe(gl, { childList: true, subtree: true });
    deathObs.observe(document.body, { childList: true, subtree: true });

    // 3. Fast interval check on victoryDisplay & encounterDiscard
    setInterval(() => {
      const g = window.game || window.LotrEngine?.game;
      if (!g) return;
      if (g.victoryDisplay && g.victoryDisplay.some(c => c && (c.id === 'dungeon_jailor' || c.id === 'dungeon_jailer') && !c._deathSoundPlayed)) {
        const jailor = g.victoryDisplay.find(c => c && (c.id === 'dungeon_jailor' || c.id === 'dungeon_jailer') && !c._deathSoundPlayed);
        if (jailor) {
          jailor._deathSoundPlayed = true;
          playDungeonJailorDiesImmediately();
        }
      }
      if (g.encounterDiscard && g.encounterDiscard.some(c => c && (c.id === 'dungeon_jailor' || c.id === 'dungeon_jailer') && !c._deathSoundPlayed)) {
        const jailor = g.encounterDiscard.find(c => c && (c.id === 'dungeon_jailor' || c.id === 'dungeon_jailer') && !c._deathSoundPlayed);
        if (jailor) {
          jailor._deathSoundPlayed = true;
          playDungeonJailorDiesImmediately();
        }
      }
    }, 150);
  }
